import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Check for correlation pairs with |r| >= 0.6
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Remove near-duplicates (keep one from each pair)
    selected_features = set(feats.ids)
    for fid1, fid2 in correlated_pairs:
        if fid1 in selected_features and fid2 in selected_features:
            # Prefer the one with higher t-statistic
            i1 = feats.column(fid1)
            i2 = feats.column(fid2)
            t1 = stats.ttest_ind(feats.x[feats.y==1,i1], feats.x[feats.y==0,i1]).statistic
            t2 = stats.ttest_ind(feats.x[feats.y==1,i2], feats.x[feats.y==0,i2]).statistic
            if abs(t1) >= abs(t2):
                selected_features.remove(fid2)
            else:
                selected_features.remove(fid1)

    # Filter to selected features
    selected_ids = list(selected_features)

    # Try to find drivers by checking stratum-specific effects
    drivers = []
    for fid in selected_ids:
        col = feats.column(fid)
        if len(set(feats.stratum)) > 1:
            # Check effect size across strata
            stratum_effects = []
            for stratum in set(feats.stratum):
                mask = np.array([s == stratum for s in feats.stratum])
                y_stratum = feats.y[mask]
                x_stratum = feats.x[mask, col]
                if len(y_stratum) > 1 and np.var(x_stratum) > 0:
                    effect = np.mean(x_stratum[y_stratum==1]) - np.mean(x_stratum[y_stratum==0])
                    stratum_effects.append(effect)
            if len(stratum_effects) > 1:
                # Check if effects are consistent (not too different)
                if np.std(stratum_effects) < 0.5 * np.abs(np.mean(stratum_effects)):
                    drivers.append(fid)
        else:
            # No strata, just check overall effect
            effect = np.mean(feats.x[feats.y==1,col]) - np.mean(feats.x[feats.y==0,col])
            if np.abs(effect) > 0.1:
                drivers.append(fid)

    # If no drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top drivers by effect size (limit to MAX_DRIVERS)
    drivers = drivers[:MAX_DRIVERS]

    # Build regression variables
    columns = tuple(selected_ids)
    products = ()
    loadings = {fid: 1.0 for fid in selected_ids}

    return Design(drivers=tuple(drivers), columns=columns, products=products, loadings=loadings)
